        const dirSign = this.clockwise ? -1 : 1;

        each(this._indicatorAxes, function (indicatorAxis, idx) {
            indicatorAxis.setExtent(this.r0, this.r);
            let angle = (this.startAngle + dirSign * idx * Math.PI * 2 / this._indicatorAxes.length);
