import { createChart, getECModel, getGraphicElements } from '../../../core/utHelper';
import { EChartsType } from '@/src/echarts';
import RadarModel from '@/src/coord/radar/RadarModel';
import Radar from '@/src/coord/radar/Radar';

describe('coord_radar_clockwise', function () {

    let chart: EChartsType;

    beforeEach(function () {
        chart = createChart({ width: 400, height: 400 });
    });

    afterEach(function () {
        chart.dispose();
    });

    function setRadarOption(radarOption: object): Radar {
        chart.setOption({
            radar: Object.assign({
                center: ['50%', '50%'],
                radius: 100,
                startAngle: 90,
                indicator: [
                    { name: 'a', max: 100 },
                    { name: 'b', max: 100 },
                    { name: 'c', max: 100 },
                    { name: 'd', max: 100 }
                ]
            }, radarOption),
            series: [{
                type: 'radar',
                data: [{ value: [10, 20, 30, 40] }]
            }]
        }, true);

        return (getECModel(chart).getComponent('radar', 0) as RadarModel).coordinateSystem;
    }

    function expectPointCloseTo(pt: number[], x: number, y: number): void {
        expect(pt[0]).toBeCloseTo(x, 4);
        expect(pt[1]).toBeCloseTo(y, 4);
    }

    it('defaults to counterclockwise (backward compatible)', function () {
        const radar = setRadarOption({});
        const r = radar.r;

        expect(radar.clockwise).toBe(false);

        // startAngle 90 -> indicator 0 on top.
        expectPointCloseTo(radar.coordToPoint(r, 0), radar.cx, radar.cy - r);
        // Counterclockwise -> indicator 1 on the left.
        expectPointCloseTo(radar.coordToPoint(r, 1), radar.cx - r, radar.cy);
        expectPointCloseTo(radar.coordToPoint(r, 2), radar.cx, radar.cy + r);
        expectPointCloseTo(radar.coordToPoint(r, 3), radar.cx + r, radar.cy);
    });

    it('lays indicators out clockwise when `clockwise: true`', function () {
        const radar = setRadarOption({ clockwise: true });
        const r = radar.r;

        expect(radar.clockwise).toBe(true);

        // The first indicator must still sit at `startAngle`.
        expectPointCloseTo(radar.coordToPoint(r, 0), radar.cx, radar.cy - r);
        // Clockwise -> indicator 1 on the right.
        expectPointCloseTo(radar.coordToPoint(r, 1), radar.cx + r, radar.cy);
        expectPointCloseTo(radar.coordToPoint(r, 2), radar.cx, radar.cy + r);
        expectPointCloseTo(radar.coordToPoint(r, 3), radar.cx - r, radar.cy);
    });

    it('mirrors the angle set so `startAngle` is still honored', function () {
        const ccw = setRadarOption({ startAngle: 0 });
        expectPointCloseTo(ccw.coordToPoint(ccw.r, 0), ccw.cx + ccw.r, ccw.cy);
        expectPointCloseTo(ccw.coordToPoint(ccw.r, 1), ccw.cx, ccw.cy - ccw.r);

        const cw = setRadarOption({ startAngle: 0, clockwise: true });
        expectPointCloseTo(cw.coordToPoint(cw.r, 0), cw.cx + cw.r, cw.cy);
        expectPointCloseTo(cw.coordToPoint(cw.r, 1), cw.cx, cw.cy + cw.r);
    });

    it('keeps all axis names rendered in both directions', function () {
        function getAxisNames(): string[] {
            const names: string[] = [];
            const els = getGraphicElements(chart, 'radar', 0);
            for (let i = 0; i < els.length; i++) {
                const el = els[i] as any;
                if (el.anid === 'name' && el.style && el.style.text != null) {
                    names.push(el.style.text);
                }
            }
            return names.sort();
        }

        setRadarOption({});
        expect(getAxisNames()).toEqual(['a', 'b', 'c', 'd']);

        setRadarOption({ clockwise: true });
        expect(getAxisNames()).toEqual(['a', 'b', 'c', 'd']);
    });

    it('reverses the data polygon point order accordingly', function () {
        const ccw = setRadarOption({});
        const ccwP1 = ccw.dataToPoint(20, 1);
        expect(ccwP1[0]).toBeLessThan(ccw.cx);

        const cw = setRadarOption({ clockwise: true });
        const cwP1 = cw.dataToPoint(20, 1);
        expect(cwP1[0]).toBeGreaterThan(cw.cx);
    });
});
```

Notes on the sketch:

* `radar.cx`/`radar.cy`/`radar.r` are read off the coordinate system rather than hard-coded so the
  assertions do not depend on `createBoxLayoutReference` details.
* Angles are asserted through `coordToPoint()` instead of raw `indicatorAxis.angle`, because the
  `Math.atan2(sin, cos)` normalization makes the exact sign at ±π floating-point fragile
  (e.g. `atan2(sin(2π), cos(2π))` yields `-2.4e-16`, and `atan2(sin(-π), cos(-π))` yields `-π`).
  `toBeCloseTo(..., 4)` on the resulting points is stable.
* `anid === 'name'` is the marker `AxisBuilder` sets on the axis-name text
  (`/workspace/src/component/axis/AxisBuilder.ts` — `textEl.anid = 'name';`), which makes the label
  assertion selector-based rather than index-based.
* If `Object.assign` is undesirable for the ES3 target of the *source* tree, note the tests compile
  with `test/ut/tsconfig.json` (`target: ES6`) so it is fine; alternatively use
  `zrUtil.extend` imported from `zrender/src/core/util`.

## 5. Verification

```bash
# 1. Type check the whole source tree (must be clean).
cd /workspace && npx tsc --noEmit -p tsconfig.json

# 2. Lint the touched files.
cd /workspace && npx eslint src/coord/radar/Radar.ts src/coord/radar/RadarModel.ts

# 3. Run the new unit test only.
cd /workspace && npx jest --config test/ut/jest.config.cjs --coverage=false -t "coord_radar_clockwise"

# 4. Run the whole UT suite to prove no regression.
cd /workspace && npm run test

# 5. Visual check (manual): serve the test dir and open the new page.
cd /workspace && npm run test:visual   # then open test/radar-clockwise.html
```

Expected results:

* `tsc --noEmit` reports no new errors (`clockwise` is a declared member of `RadarOption`, so
  `radarModel.get('clockwise')` type-checks and returns `boolean`).
* The new spec passes all five cases.
* No other UT changes status — the default `clockwise: false` makes `dirSign === 1`, i.e. the exact
  arithmetic that exists today.
* In `test/radar-clockwise.html`, chart `main0` (default) and chart `main1` (`clockwise: true`) are
  mirror images about the vertical axis, both with correctly positioned, non-overlapping axis names.

## 6. Risks / open questions

1. **Default value.** I chose `clockwise: false` so that every existing radar chart renders
   identically (the requirement says the change must not break "the rest of the radar rendering
   contract"). Every other ECharts component that has `clockwise` defaults it to `true`
   (`src/component/polar/install.ts:43`, `src/chart/pie/PieSeries.ts:220`,
   `src/chart/gauge/GaugeSeries.ts:209`, `src/chart/sunburst/SunburstSeries.ts:227`,
   `src/chart/chord/ChordSeries.ts:308`), so there is a naming-consistency argument for `true`. If the
   upstream decision was `true`, the *only* change needed is the literal in Edit 6 (plus the doc
   comments and the two "default" assertions in the spec) — the mechanism is identical.
2. **`pointToData` nearest-axis search.** `/workspace/src/coord/radar/Radar.ts:98-123` uses
   `Math.abs(radian - indicatorAxis.angle)` without wrap-around handling, so an axis at `+π` and a
   pointer at `-π` are considered maximally far apart. This is a pre-existing bug, direction-agnostic,
   and deliberately left untouched to keep the change minimal. It is worth flagging in review.
3. **Split-area winding.** `_buildSplitLineAndArea` (`src/component/radar/RadarView.ts:129-165`)
   produces ring polygons whose winding flips with `clockwise`. Canvas/SVG fill for the
   outer-forward/inner-reversed pair is winding-symmetric, so no visual change is expected, but the
   `shape: 'polygon'` + `splitArea` case is the one to eyeball in the visual test.
4. **`radar.axisName.formatter` / `triggerEvent`.** Both are keyed off the indicator model, not the
   angle, so they follow the reordered axes automatically. No action.
5. **Docs.** The option reference lives in the separate `apache/echarts-doc` repository; adding
   `radar.clockwise` there is out of scope for this repo but should be filed as a follow-up.
6. **`echarts.util.merge` in the visual test.** `echarts.util` is exported from
   `src/export/core.ts`; if `merge` is not on the public `util` surface in this build, replace the
   `makeOption` helper with plain object literals per chart.

